const body = $('Webhook').first().json.body || {};
const suffix = "\n\nتعليمات صارمة لازم تتبعها بالظبط:\n" +
  "1) كمّل تلعب دور الدكتور الحقيقي بنفس أسلوب كتابته على الموبايل وقت الشغل: عربي طبيعي وسريع، جمل قصيرة أحيانًا، من غير رسمية زيادة أو تقرير منمّق.\n" +
  "2) اختبر البوت بجدية زي مراجعة حقيقية: اسأل متابعة لو رده كان عام أو ناقص، وراقب التفاصيل اللي انت نفسك ذكرتها قبل كده — لو البوت نسيها أو تجاهلها ده أهم حاجة تمسكها.\n" +
  "3) لو حسيت إن رد البوت اللي فات فيه مشكلة فعلية (اتجاهل معلومة قلتهالك، رد غير منطقي طبيًا، ناقض نفسه، عمل حاجة غلط، أو تجاهل تعليمات واضحة) ابدأ ردك بسطر لوحده بالظبط كده: [FLAG: وصف مختصر جدًا للمشكلة] وبعدين كمّل ردك العادي في سطر جديد. متستخدمش [FLAG] إلا وانت متأكد فعلاً إن فيه مشكلة.\n" +
  "4) رد فقط بالرسالة اللي هيكتبها الدكتور (زائد سطر [FLAG] لو محتاج) — من غير أي شرح أو تعليق أو Markdown أو علامات اقتباس.\n" +
  "5) لو الاختبار خلص فعلاً اكتب END_TEST وحده من غير أي كلام قبله أو بعده.";
const system = String(body.system_prompt || '') + suffix;

const contents = [];
for (const h of (body.history || [])) {
  contents.push({ role: h.role === 'assistant' ? 'model' : 'user', parts: [{ text: String(h.content || '') }] });
}
if (contents.length === 0) {
  contents.push({ role: 'user', parts: [{ text: String(body.message || 'ابدأ') }] });
}

return [{ json: { geminiBody: {
  system_instruction: { parts: [{ text: system }] },
  contents,
  generationConfig: { temperature: 0.95 }
} } }];
